export const strengthenedFoundationLessonIds = Object.keys(allStrengthenedLessons).map(Number).sort((left, right) => left - right);

export function getStrengthenedFoundationLesson(id: number) {
  return allStrengthenedLessons[id] ?? null;
}

export function getStrengthenedLessonContent(lesson: Pick<LessonDefinition, "id" | "title" | "topic" | "outcome">): LessonContent | null {
  const strengthened = getStrengthenedFoundationLesson(lesson.id);
  if (!strengthened) return null;
  return {
    summary: strengthened.introduction,
    explanation: [strengthened.basicIdea, strengthened.howItWorks, strengthened.whyItWorks].join(" "),
    keyIdeas: [
      ...strengthened.learningObjectives,
      `Common mistake: ${strengthened.misconceptions[0]?.mistake ?? "Check the definition before solving."}`,
    ],
    realWorldExamples: strengthened.realLifeExamples.map((example) => `${example.context}: ${example.connection}`),
    controlGuide: [
      strengthened.interaction.initialState,
      ...strengthened.guidedExploration.map((step) => step.prompt),
      strengthened.interaction.accessibilityAlternative,
    ],
    formulas: strengthened.formulas.map(toLessonFormula),
    workedConnection: `${strengthened.workedExamples[0]?.prompt ?? lesson.title}: ${(strengthened.workedExamples[0]?.steps ?? []).join(" ")} Answer: ${strengthened.workedExamples[0]?.answer ?? lesson.outcome}`,
    knowMore: [
      `Definition: ${strengthened.definitions[0]?.statement}`,
      `Condition: ${strengthened.conditionsAndRestrictions[0]}`,
      `Correction: ${strengthened.misconceptions[0]?.correction}`,
      `Exit check: ${strengthened.exitCheck[0]?.prompt}`,
    ],
  };
}

