export function createStrengthenedFoundationChallenge(lessonId: number): FoundationChallenge | null {
  return allStrengthenedChallenges[lessonId] ?? null;
}

function toLessonFormula(formula: StrengthenedLesson["formulas"][number]): LessonFormula {
  return {
    label: formula.label,
    expression: formula.expression,
    explanation: [
      ...formula.variables.map((variable) => `${variable.symbol}: ${variable.meaning}`),
      ...(formula.restrictions ?? []),
    ].join("; "),
  };
}

function numberTheoryLesson(seed: NumberTheorySeed): StrengthenedLesson {
  const code = seed.misconception[0];
  const category = seed.category ?? "Numbers and Arithmetic";
  const topic = seed.topic ?? "Numbers and Number Theory";
  return {
    id: seed.id,
    title: seed.title,
    route: seed.route ?? `/lessons/numbers-and-arithmetic/${seed.id}-${seed.slug}`,
    category,
    topic,
    lessonType: seed.lessonType ?? (seed.representation === "tree_diagram" ? "procedure" : "concept"),
    learningObjectives: [
      `Define ${seed.title} accurately.`,
      `Use a ${seed.representation.replace(/_/g, " ")} to explain ${seed.title}.`,
      `Solve a practice task and correct a common mistake about ${seed.title}.`,
    ],
    prerequisites: ["Whole numbers", "Multiplication and division facts", "Number-line order"],
    keyVocabulary: seed.vocabulary.map(([term, meaning]) => ({ term, meaning })),
    introduction: seed.intro,
    basicIdea: seed.basicIdea,
    howItWorks: seed.how,
    whyItWorks: seed.why,
    definitions: [{ id: `${seed.slug}-definition`, statement: seed.definition }],
    facts: seed.facts.map((statement, index) => ({ id: `${seed.slug}-fact-${index + 1}`, statement })),
    formulas: seed.formula ? [seed.formula] : [],
    conditionsAndRestrictions: seed.restrictions,
    representations: [{ id: `${seed.slug}-representation`, type: seed.representation, learningPurpose: `Show the exact structure of ${seed.title}.` }],
    workedExamples: [{ id: `${seed.slug}-worked-1`, prompt: seed.worked[0], steps: seed.worked[1], answer: seed.worked[2] }],
    realLifeExamples: seed.examples.map(([context, connection], index) => ({ id: `${seed.slug}-real-${index + 1}`, context, connection })),
    misconceptions: [{ code, mistake: seed.misconception[1], correction: seed.misconception[2] }],
    interaction: {
      id: `${seed.slug}-interaction`,
      learningPurpose: `Connect ${seed.title} to its definition, examples, and non-examples.`,
      parameters: [{ id: "number", label: "Number", validRange: seed.id === 61 || seed.id === 62 ? [-20, 20] : [1, 60] }],
      initialState: `Start with the worked example for ${seed.title}.`,
      dynamicFeedback: `The display should name why the selected value does or does not match ${seed.title}.`,
      successCriteria: [`Classify an example of ${seed.title}.`, "Explain the misconception in words."],
      accessibilityAlternative: "Provide the same classification as a short text table.",
    },
    guidedExploration: [
      { id: "predict", prompt: `Predict whether the selected value is a correct example of ${seed.title}.` },
      { id: "observe", prompt: "Change one value and read the classification." },
      { id: "conclude", prompt: "Explain the result using the definition." },
    ],
    practice: [
      practice(`${seed.slug}-recognition`, `Identify one correct example of ${seed.title}.`, seed.practiceAnswers[0], code, "recognition"),
      practice(`${seed.slug}-direct`, `Answer a direct question about ${seed.title}.`, seed.practiceAnswers[1], code, "direct"),
      practice(`${seed.slug}-multi`, `Solve a two-step task using ${seed.title}.`, seed.practiceAnswers[2], code, "multi_step"),
      practice(`${seed.slug}-error`, `Find the mistake in a claim about ${seed.title}.`, seed.practiceAnswers[3], code, "error_diagnosis"),
      practice(`${seed.slug}-transfer`, `Use ${seed.title} in a new situation.`, seed.practiceAnswers[4], code, "transfer"),
    ],
    challenge: {
      id: `${seed.slug}-challenge`,
      prompt: seed.challenge.prompt,
      successCriteria: ["Uses the exact definition", "Gives the correct value or classification", "Avoids the named misconception"],
      hints: [seed.challenge.hint, "Check the condition in the definition."],
    },
    exitCheck: [{ id: `${seed.slug}-exit`, prompt: `Give one example and one non-example of ${seed.title}.`, answer: seed.practiceAnswers[0], criterion: "The answer must match the definition." }],
    accessibilityNotes: ["Announce the selected value and classification.", "Do not rely only on colour to show correctness."],
    expertReviewRequired: false,
  };
}

function practice(
  id: string,
  prompt: string,
  answer: string,
  misconceptionTag: string,
  difficulty: StrengthenedLesson["practice"][number]["difficulty"],
): StrengthenedLesson["practice"][number] {
  return {
    id,
    prompt,
    answer,
    hints: ["Start with the definition.", "Use the number line or model.", "Check the condition."],
    workedSolution: ["Identify the mathematical object.", "Apply the lesson definition.", "Check the answer against the model."],
    misconceptionTag,
    difficulty,
    parameterConstraints: ["Use values that match this lesson's number set."],
  };
}
